diff --git a/tests/auth-service.test.js b/tests/auth-service.test.js
index 8ea5570..663721e 100644
--- a/tests/auth-service.test.js
+++ b/tests/auth-service.test.js
@@ -2,18 +2,12 @@ import { test } from 'node:test';
 import assert from 'node:assert/strict';
 import { findByEmail, isActive } from '../src/services/auth-service.js';

-test('findByEmail ignores soft-deleted users', (t, done) => {
-  findByEmail('alan@example.com', (err, user) => {
-    assert.equal(err, null);
-    assert.equal(user, null);
-    done();
-  });
+test('findByEmail ignores soft-deleted users', async () => {
+  const user = await findByEmail('alan@example.com');
+  assert.equal(user, null);
 });

-test('isActive is true for a live user', (t, done) => {
-  isActive('ada@example.com', (err, active) => {
-    assert.equal(err, null);
-    assert.equal(active, true);
-    done();
-  });
+test('isActive is true for a live user', async () => {
+  const active = await isActive('ada@example.com');
+  assert.equal(active, true);
 });
diff --git a/tests/order-service.test.js b/tests/order-service.test.js
index 4cbad96..8f00eb3 100644
--- a/tests/order-service.test.js
+++ b/tests/order-service.test.js
@@ -2,19 +2,13 @@ import { test } from 'node:test';
 import assert from 'node:assert/strict';
 import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

-test('listOrdersForUser returns only that user orders', (t, done) => {
-  listOrdersForUser(1, (err, orders) => {
-    assert.equal(err, null);
-    assert.equal(orders.length, 2);
-    assert.ok(orders.every((o) => o.user_id === 1));
-    done();
-  });
+test('listOrdersForUser returns only that user orders', async () => {
+  const orders = await listOrdersForUser(1);
+  assert.equal(orders.length, 2);
+  assert.ok(orders.every((o) => o.user_id === 1));
 });

-test('totalPaidCents counts only paid orders', (t, done) => {
-  totalPaidCents((err, total) => {
-    assert.equal(err, null);
-    assert.equal(total, 4200 + 9900 + 500);
-    done();
-  });
+test('totalPaidCents counts only paid orders', async () => {
+  const total = await totalPaidCents();
+  assert.equal(total, 4200 + 9900 + 500);
 });

